async function taskRequesterOrganization(user:ReturnType<typeof actor>,task:Record<string,any>){if(!sql)return null;const source=await sql`SELECT created_by FROM nexusflow.records WHERE id=${String(task.id)} AND kind='tasks' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id}`,requesterId=String(source[0]?.created_by||"");if(!requesterId)return null;const account=await sql`SELECT org_id FROM nexusflow.users WHERE id=${requesterId} AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id}`;return account[0]?.org_id?String(account[0].org_id):null;}
async function hasDispatchForTask(user:ReturnType<typeof actor>,taskId:string){if(!sql)return false;const rows=await sql`SELECT id FROM nexusflow.records WHERE kind='dispatch' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} AND data->>'task_id'=${taskId} AND data->>'status' NOT IN ('rejected','cancelled') LIMIT 1`;return rows.length>0;}
