app.post("/api/config/:id/publish",async c=>{const user=actor(c);if(!["super_admin","center_director"].includes(user.role))return c.json({error:"forbidden"},403);if(!sql)return c.json({error:"DATABASE_URL required"},503);const body=await c.req.json().catch(()=>({}));if(!String(body.reason||"").trim())return c.json({error:"publish reason required"},400);const result=await sql.begin(async tx=>{const rows=await tx`SELECT id,data FROM nexusflow.records WHERE id=${c.req.param("id")} AND kind='config' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} FOR UPDATE`;if(!rows[0])return null;const current=rows[0].data as any;if(current.status!=="draft"||current.key!=="task_types"||!Array.isArray(current.value?.types)||!current.value.types.every((x:any)=>typeof x==="string"&&/^[a-z0-9-]{2,64}$/.test(x)))throw new Error("invalid configuration draft");await tx`SELECT pg_advisory_xact_lock(hashtext(${`config:${user.tenant_id}:${current.key}`}))`;await tx`UPDATE nexusflow.records SET data=data||${tx.json({status:"superseded"} as any)},updated_at=now() WHERE kind='config' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} AND data->>'key'=${current.key} AND data->>'status'='published'`;const versions=await tx`SELECT max((data->>'version')::int) AS version FROM nexusflow.records WHERE kind='config_versions' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} AND data->>'key'=${current.key}`,version=Math.max(Number(current.version||0),Number(versions[0]?.version||0))+1,published_at=new Date().toISOString();await insertRecord(tx,user,"config_versions",{config_id:rows[0].id,key:current.key,version,snapshot:current,reason:body.reason,published_by:user.id,published_at});await tx`UPDATE nexusflow.records SET data=data||${tx.json({status:"published",version,published_at,change_reason:body.reason} as any)},updated_at=now() WHERE id=${rows[0].id} AND kind='config'`;await addAudit(tx,user,"config.publish","config",String(rows[0].id),{version,reason:body.reason});return String(rows[0].id);});return result?c.json(await getRecord(user,"config",result)):c.json({error:"not found"},404);});
app.get("/api/admin/users",async c=>{if(!canManage(actor(c)))return c.json({error:"forbidden"},403);if(!sql)return c.json({items:[]});const user=actor(c);const rows=await sql`SELECT id,username,display_name,role,tenant_id,org_id,status,created_at FROM nexusflow.users WHERE (${user.role==='super_admin'} OR tenant_id IS NOT DISTINCT FROM ${user.tenant_id}) AND (${['super_admin','center_director'].includes(user.role)} OR org_id IS NOT DISTINCT FROM ${user.org_id}) ORDER BY created_at`;return c.json({items:rows});});
