app.patch("/api/admin/users/:id/binding",async c=>{const user=actor(c);if(!["super_admin","center_director"].includes(user.role)||!sql)return c.json({error:"forbidden"},403);const body=await c.req.json().catch(()=>({})),roles=["member","project_lead","department_deputy","department_director","center_deputy","center_director"];if(!String(body.reason||"").trim()||!roles.includes(String(body.role)))return c.json({error:"role and audit reason required"},400);const orgId=body.org_id?String(body.org_id):null;if(orgId&&!await getRecord(user,"orgs",orgId))return c.json({error:"organization not found"},404);const result=await sql.begin(async tx=>{const rows=await tx`SELECT id,role,org_id FROM nexusflow.users WHERE id=${c.req.param("id")} AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} FOR UPDATE`;if(!rows[0])return null;if(rows[0].role==="super_admin"&&user.role!=="super_admin")throw new Error("only a super administrator may change a super administrator");if(["super_admin","center_director"].includes(String(body.role))&&user.role!=="super_admin")throw new Error("only a super administrator may grant that role");await tx`UPDATE nexusflow.users SET role=${body.role},org_id=${orgId},updated_at=now() WHERE id=${rows[0].id}`;await tx`UPDATE nexusflow.records SET data=data||${tx.json({org_id:orgId} as any)},updated_at=now() WHERE kind='people' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} AND data->>'user_id'=${String(rows[0].id)}`;await addAudit(tx,user,"admin.user_binding","user",String(rows[0].id),{role:body.role,org_id:orgId,reason:body.reason});return {id:String(rows[0].id),changed:rows[0].role!==body.role||rows[0].org_id!==orgId};});if(!result)return c.json({error:"not found"},404);if(result.changed)await revokeUserSessions(result.id);return c.json({ok:true});});
