app.post("/api/visibility_grants/:id/revoke",async c=>{const user=actor(c);if(!canManage(user)||!sql)return c.json({error:"forbidden"},403);const grant=await getRecord(user,"visibility_grants",c.req.param("id"));if(!grant)return c.json({error:"not found"},404);if(!await canProjectAction(user,String(grant.project_id),"edit"))return c.json({error:"project edit permission required"},403);const result=await sql.begin(async tx=>{const rows=await tx`SELECT id,data FROM nexusflow.records WHERE id=${grant.id} AND kind='visibility_grants' AND tenant_id IS NOT DISTINCT FROM ${user.tenant_id} FOR UPDATE`;if(!rows[0]||(rows[0].data as any).status==="revoked")throw new Error("grant already revoked");await tx`UPDATE nexusflow.records SET data=data||${tx.json({status:"revoked",revoked_by:user.id,revoked_at:new Date().toISOString()} as any)},updated_at=now() WHERE id=${grant.id} AND kind='visibility_grants'`;await addAudit(tx,user,"visibility_grant.revoke","visibility_grants",String(grant.id));return {ok:true};});return c.json(result);});
