app.post("/api/invitations",async c=>{const user=actor(c);if(!canManage(user))return c.json({error:"forbidden"},403);const body=await c.req.json().catch(()=>({}));const elevated=["center_director","super_admin"].includes(user.role);const roles=elevated?["member","project_lead","department_deputy","department_director","center_deputy"]:["member","project_lead"];const role=String(body.role||"member"),org_id=String(body.org_id||user.org_id||"");if(!roles.includes(role)||!org_id||(!elevated&&!await canManageOrganization(user,org_id)))return c.json({error:"invalid invite role or organization scope"},400);const expires_at=body.expires_at?new Date(String(body.expires_at)):new Date(Date.now()+7*86400000);if(!Number.isFinite(expires_at.valueOf())||expires_at<=new Date()||expires_at.getTime()>Date.now()+30*86400000)return c.json({error:"invitation expiry must be within 30 days"},400);const token=crypto.randomUUID()+crypto.randomUUID(),token_hash=await hashText(token);const invitation=await createRecord(user,"invitations",{role,org_id,token_hash,status:"active",expires_at:expires_at.toISOString(),created_by:user.id});return c.json({invitation,token},201);});
